function splitNum(num) {
  const digits = String(num).split('').map(Number);
  digits.sort((a, b) => a - b);
  let num1 = 0;
  let num2 = 0;

  for (let i = 0; i < digits.length; i++) {
    if (i % 2 === 0) {
      num1 = num1 * 10 + digits[i];
    } else {
      num2 = num2 * 10 + digits[i];
    }
  }
  return num1 + num2;
}

