function splitNum(num) {
  const digits = String(num).split('').map(Number);
  const n = digits.length;
  const build = (list) => list.sort((a, b) => a - b).reduce((value, d) => value * 10 + d, 0);
  let best = Infinity;
  for (let mask = 0; mask < (1 << n); mask++) {
    const first = [], second = [];
    for (let k = 0; k < n; k++) ((mask >> k) & 1 ? first : second).push(digits[k]);
    best = Math.min(best, build(first) + build(second));
  }
  return best;
}

