function generate(rand, size) {
  const length = size === 'large' ? 9 : 2 + Math.floor(rand() * 6);
  const zeroBias = rand() < 0.3 ? 0.5 : 0.1;
  let text = String(1 + Math.floor(rand() * 9));
  for (let k = 1; k < length; k++) text += rand() < zeroBias ? '0' : String(Math.floor(rand() * 10));
  return [Number(text)];
}
